let MACHINE_IDS = [];
for (let i = 1; i <= 1000; i++) {
    MACHINE_IDS.push(`MCH-${String(i).padStart(4, "0")}`);
}
// Função sinusoidal com randomização
function sinusoidal(base, amplitude, period) {
    const t = Date.now() % period; // tempo relativo, sem estado
    return base + amplitude * Math.sin(t / period);
}

// Gera um objeto por máquina
function generateMachine(id) {

    // Cada parâmetro recebe um período aleatório entre 3s e 30s
    const randPeriod = () => Math.floor(Math.random() * (30000 - 3000)) + 3000;

    return {
        machineId: id,
        timestamp: Date.now(),

        temperature: sinusoidal(60, 20, randPeriod()),
        vibration: sinusoidal(2, 1.5, randPeriod()),
        loadPercentage: sinusoidal(50, 40, randPeriod()),
        rpm: sinusoidal(2000, 800, randPeriod()),
        voltage: sinusoidal(230, 10, randPeriod()),
        current: sinusoidal(10, 8, randPeriod()),
        pressure: sinusoidal(6, 4, randPeriod()),
        humidity: sinusoidal(40, 30, randPeriod()),
        oilLevel: sinusoidal(70, 20, randPeriod()),
        coolantTemperature: sinusoidal(55, 15, randPeriod()),

        cycleCount: Math.floor(Math.random() * 200000),
        powerConsumption: sinusoidal(3, 1.5, randPeriod()),
        torque: sinusoidal(100, 40, randPeriod()),
        bearingWear: Math.random() * 20,
        noiseLevel: sinusoidal(60, 10, randPeriod()),

        errorCode: Math.random() < 0.02 ? 1 : 0,
        networkLatency: sinusoidal(10, 5, randPeriod()),
        uptimeHours: Math.random() * 5000,

        status: "OK"
    };
}

// Ajusta status
function adjustStatus(obj) {
    if (obj.errorCode === 1) obj.status = "ERROR";
    else if (obj.vibration > 4 || obj.temperature > 85) obj.status = "WARNING";
    return obj;
}

// Gera todas as máquinas
msg.payload = MACHINE_IDS.map(id => adjustStatus(generateMachine(id)));

return msg;

